// SI disclosure: written with the assistance of an SI coding tool (Claude) and reviewed by the team.
// Discovery engine UI: question -> suggested variables (documented rules), variable catalogue, Evidence Cards and the
// Magallanes "datasets disagree" case. Everything shown comes from discovery.json, generated by pipeline/discovery.py.
import { useCallback, useState } from 'react';
import { COLOR_A, COLOR_B, intervals, PlotFigure, type Interval } from './charts';
import { num, pval, signed } from './format';

export interface CatalogEntry {
  id: string; label: string; product: string; source_type: string; institution: string; unit: string; spatial: string;
  temporal: string; coverage: string; access: string; status: string; depends_on: string[]; limitations: string[]; questions: string[];
}
export interface Question {
  id: string; label: string; prompt: string; variables: { id: string; why: string }[];
  relations: { a: string; b: string; type: string }[]; unavailable?: string;
  open: { kind: 'lab' | 'coast' | 'magallanes' | 'case'; region?: string; x?: string; y?: string; index?: number };
}
type Res = { slope: number | null; r?: number; ci: [number, number] | null; p: number | null; q?: number | null; unit: string; period: string; count_main?: number; count_alt?: number };
type Check = { source: string; kind: string; agreement: string; years: number; ours: number[] | null; theirs: number[]; dependency: string; scope?: string };
export interface Card {
  id: string; title: string; status: string; variable: string; territory: string; result: Res;
  source: { product: string; type: string; resolution: string; access: string };
  analysis: { method: string; correction: string; sensitivity: unknown };
  checks: Check[]; can: string; cannot: string; open?: string[]; limitations: string[];
  question?: string; links?: { label: string; url: string }[];
}
export interface Discovery { generated_at: string; catalog: CatalogEntry[]; relation_types: Record<string, string>; questions: Question[]; cards: Card[]; agreement_note?: string }

const STATUS_LABEL: Record<string, string> = {
  integrated: 'Integrated', available_not_processed: 'Available at NASA, not processed', planned: 'Planned',
  unavailable: 'Unavailable', validation_only: 'Validation only',
};
const NE = 'Not evaluated';

export function QuestionStart({ d, onOpen }: { d: Discovery; onOpen: (q: Question) => void }) {
  // ?q=<question id> opens a question directly (shareable demo links)
  const [qid, setQid] = useState<string | null>(() => new URLSearchParams(location.search).get('q'));
  const q = d.questions.find((x) => x.id === qid);
  const cat = Object.fromEntries(d.catalog.map((c) => [c.id, c]));
  return (
    <section aria-labelledby="h-question" className="question-start">
      <h2 id="h-question"><span className="step">0</span> What do you want to investigate?</h2>
      <p>Pick a question. The app suggests the NASA variables that can help — and says which ones are not available yet.</p>
      <div className="chips" role="group" aria-label="Questions">
        {d.questions.map((x) => (
          <button key={x.id} className="chip" aria-pressed={x.id === qid} onClick={() => setQid(x.id)}>{x.label}</button>
        ))}
      </div>
      {q && (
        <div className="question-panel">
          <p className="lede-small"><strong>{q.prompt}</strong></p>
          <ul className="var-suggest">
            {q.variables.map((v) => {
              const c = cat[v.id];
              return (
                <li key={v.id} className={`status-${c.status}`}>
                  <strong>{c.label}</strong> <span className={`sbadge s-${c.status}`}>{STATUS_LABEL[c.status]}</span>
                  <span>{v.why}</span>
                  <span className="muted">{c.product} · {c.spatial} · {c.coverage}</span>
                </li>
              );
            })}
          </ul>
          <p className="hint">How these variables relate: {q.relations.map((r) => `${cat[r.a].label} – ${cat[r.b].label}: ${d.relation_types[r.type]}`).join('; ')}.</p>
          {q.unavailable && <p className="callout" role="note">{q.unavailable}</p>}
          <button className="primary" onClick={() => onOpen(q)}>Open this investigation</button>
        </div>
      )}
      <details className="catalog">
        <summary>Variable catalogue: what each product is and whether it is integrated</summary>
        <div className="table-scroll">
          <table className="region-table">
            <caption>Status "Integrated" means real NASA data processed by this project's pipeline. Other entries are listed so nobody mistakes them for results.</caption>
            <thead><tr><th scope="col">Variable</th><th scope="col">Product</th><th scope="col">Type</th><th scope="col">Resolution</th><th scope="col">Coverage</th><th scope="col">Status</th><th scope="col">Limitations</th></tr></thead>
            <tbody>
              {d.catalog.map((c) => (
                <tr key={c.id}><th scope="row">{c.label}</th><td>{c.product}</td><td>{c.source_type}</td><td>{c.spatial}, {c.temporal}</td>
                  <td>{c.coverage}</td><td>{STATUS_LABEL[c.status]}</td><td>{c.limitations.join('; ')}</td></tr>
              ))}
            </tbody>
          </table>
        </div>
      </details>
    </section>
  );
}

const fmtRes = (r: Res) => {
  if (r.count_main != null) return `${r.count_main} regions with p < 0.05 in the main window vs ${r.count_alt} in the shorter one (${r.period})`;
  const est = r.r != null ? `r = ${signed(r.r)}` : r.slope != null ? `${signed(r.slope)} ${r.unit}` : NE;
  const ci = r.ci ? ` (95 % CI ${num(r.ci[0])} to ${num(r.ci[1])})` : '';
  const p = r.p != null ? `, ${pval(r.p)}` : '';
  const q = r.q != null ? `, adjusted ${pval(r.q).replace('p', 'q')}` : '';
  return `${est}${ci}${p}${q} · ${r.period}`;
};

export function EvidenceCard({ c, note }: { c: Card; note?: string }) {
  const sens = c.analysis.sensitivity as
    | { label: string; period: string; slope: number; ci: [number, number]; p: number; q?: number; main: boolean }[]
    | { range_restricted: Res; nearest_pairs: Res; thresholds: { rule: string; slope: number; ci: [number, number] }[] }
    | null;
  return (
    <article className="ecard" aria-labelledby={`ec-${c.id}`}>
      <header><h3 id={`ec-${c.id}`}>{c.title}</h3><span className={`tag-exp${c.status.startsWith('confirmatory') ? ' tag-conf' : ''}`}>{c.status}</span></header>
      {c.question && <p className="ecard-q">Question: {c.question}</p>}
      <dl>
        <div><dt>A · Result</dt><dd>{c.variable}, {c.territory}: {fmtRes(c.result)}</dd></div>
        <div><dt>B · Source</dt><dd>{c.source.product} — {c.source.type}, {c.source.resolution}, via {c.source.access}</dd></div>
        <div><dt>C · Analysis</dt><dd>{c.analysis.method}. Multiple testing: {c.analysis.correction}.
          {Array.isArray(sens) && <> Period sensitivity: {sens.map((w) => `${w.main ? 'main' : 'sensitivity'} ${w.period}: ${signed(w.slope)} (${num(w.ci[0])} to ${num(w.ci[1])}), ${pval(w.p)}`).join(' · ')}.</>}
          {sens && !Array.isArray(sens) && <> Sensitivity: elevation-range-restricted comparison {fmtRes(sens.range_restricted)}; nearest-elevation pairs {fmtRes(sens.nearest_pairs)}; coastal-class rules {sens.thresholds.map((t) => `${t.rule}: ${signed(t.slope)}`).join(', ')}.</>}
          {!sens && <> Period sensitivity: {NE.toLowerCase()} for this card.</>}
        </dd></div>
        <div><dt>D · Cross-checks</dt><dd>{c.checks.length ? (
          <ul>{c.checks.map((k, i) => (
            <li key={i}>{k.source}: {k.ours ? `ours ${signed(k.ours[0])} vs ` : ''}theirs {signed(k.theirs[0])} ({num(k.theirs[1])} to {num(k.theirs[2])}), {pval(k.theirs[3])}
              {' — '}<strong>{k.agreement}</strong>{k.years ? `, ${k.years} common years` : ''}. {k.scope ? `Scope: ${k.scope}. ` : ''}Dependency: {k.dependency}.</li>
          ))}</ul>) : NE + ' (no independent product available in this version).'}{c.checks.length > 0 && note ? <span className="muted"> {note}</span> : null}</dd></div>
        <div><dt>E · Interpretation</dt><dd><strong>Supports:</strong> {c.can} <strong>Does not support:</strong> {c.cannot}
          {c.open?.length ? <> <strong>Open:</strong> {c.open.join('; ')}.</> : null}</dd></div>
        <div><dt>F · Limitations</dt><dd>{c.limitations.join('; ')}.</dd></div>
        {c.links?.length ? <div><dt>G · Sources and method</dt><dd>{c.links.map((l, i) => <span key={l.url}>{i ? ' · ' : ''}<a href={l.url}>{l.label}</a></span>)}</dd></div> : null}
      </dl>
    </article>
  );
}

export function EvidenceCards({ d }: { d: Discovery }) {
  return (
    <section aria-labelledby="h-evidence-cards" className="evidence-cards">
      <h2 id="h-evidence-cards"><span className="step">9</span> Evidence cards</h2>
      <p>The same six questions for every important result: what, from which source, how analysed, checked against what, what it
        supports and what it does not. Missing pieces say "{NE}". No confidence score is invented.</p>
      {d.cards.map((c) => <EvidenceCard key={c.id} c={c} note={d.agreement_note} />)}
    </section>
  );
}

export function MagallanesCase({ d }: { d: Discovery }) {
  const cards = ['magallanes-precip', 'magallanes-t2m'].map((id) => d.cards.find((c) => c.id === id)).filter(Boolean) as Card[];
  const make = useCallback((c: Card) => (w: number) => {
    const rows: Interval[] = [];
    if (c.result.slope != null && c.result.ci) rows.push({ name: `NASA product, regional mean (${c.result.period})`, slope: c.result.slope, lo: c.result.ci[0], hi: c.result.ci[1], color: COLOR_A });
    for (const k of c.checks) {
      const who = k.kind === 'station' ? 'Punta Arenas station' : 'ERA5 reanalysis';
      if (k.ours) rows.push({ name: `NASA, same ${k.kind === 'station' ? 'months as station' : '5 grid points'} (${k.years} yr)`, slope: k.ours[0], lo: k.ours[1], hi: k.ours[2], color: '#6b7280' });
      rows.push({ name: `${who} (${k.years} yr)`, slope: k.theirs[0], lo: k.theirs[1], hi: k.theirs[2], color: COLOR_B });
    }
    return intervals(rows, c.result.unit, w);
  }, []);
  return (
    <section aria-labelledby="h-magallanes" className="lab">
      <h2 id="h-magallanes">When Earth observation datasets disagree: Magallanes <span className="tag-exp">guided case</span></h2>
      <p className="callout" role="note"><strong>A significant trend in one dataset does not guarantee that the conclusion is robust across datasets.</strong></p>
      {cards.map((c) => (
        <div key={c.id}>
          <h3>{c.title}</h3>
          <p className="muted">{c.source.product} · {c.source.resolution} · regional mean {c.result.period}; ERA5 compared at five grid points, the station on its own months.</p>
          <PlotFigure make={make(c)} alt={`${c.variable} trends in Magallanes from several sources, each with its 95 % interval.`} />
          <p><strong>Defensible:</strong> {c.can} <strong>Not defensible:</strong> {c.cannot}</p>
        </div>
      ))}
      <ul className="teach">
        <li>Each pair of bars uses the <strong>same sample</strong>: the NASA value is recomputed on the months the station has, or at the same five grid points as ERA5.</li>
        <li>Significance is not certainty: IMERG's drying is significant on its own, yet neither the station nor ERA5 reproduces it.</li>
        <li>Two reanalyses (MERRA-2, ERA5) share many observations, so their agreement would not be fully independent either.</li>
        <li>A station is one place; a region is ~130 000 km² of fjords, mountains and steppe. IMERG is known to struggle over steep, windy terrain (Chile studies, e.g. doi:10.1016/j.atmosres.2021.105454) — a hypothesis for this case, not a tested explanation.</li>
        <li>The honest conclusion: the evidence for Magallanes is insufficient to say that the region is drying or not warming.</li>
      </ul>
    </section>
  );
}
